#!/bin/bash
fail=0
t=$(mktemp); printf '# h\n2024-12-31\taoi\t09:00\t10:00\tx\n2025-01-02\taoi\t09:00\t10:00\ty\n' > "$t"
out=$(ARCHIVE=$t bash tools/purge-archive --before 2025-01-01) || { echo "purge --before failed"; fail=1; }
[ "$out" = "purged 1 row(s) before 2025-01-01 from $t" ] || { echo "purge output: $out"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 1 ] && grep -q 'y$' "$t" || { echo "purge --before kept the wrong rows"; fail=1; }
ARCHIVE=$t bash tools/purge-archive --before 2025/06/01 >/dev/null 2>&1; [ $? = 2 ] || { echo "a malformed date should exit 2"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 1 ] || { echo "a malformed date deleted rows"; fail=1; }
ARCHIVE=$t bash tools/purge-archive --before 2025-13-45 >/dev/null 2>&1; [ $? = 2 ] || { echo "an out-of-range date should exit 2"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 1 ] || { echo "an out-of-range date deleted rows"; fail=1; }
printf '# h\n2024-12-31\taoi\t09:00\t10:00\tx\n2025-01-01\taoi\t09:00\t10:00\tz\n2025-01-02\taoi\t09:00\t10:00\ty\n' > "$t"
out=$(ARCHIVE=$t bash tools/purge-archive --before 2025-01-01) || { echo "purge --before (same day) failed"; fail=1; }
[ "$out" = "purged 1 row(s) before 2025-01-01 from $t" ] || { echo "purge output (same day): $out"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 2 ] && grep -q '^2025-01-01' "$t" || { echo "purge --before dropped the cut-off day"; fail=1; }
out=$(ARCHIVE=$t bash tools/purge-archive 2>&1 >/dev/null); [ "$out" = "usage: purge-archive --all | --before YYYY-MM-DD" ] || { echo "usage line: $out"; fail=1; }
rm -f "$t"; exit $fail

