#!/bin/bash
fail=0
t=$(mktemp); printf '# h\n2024-12-31\taoi\t09:00\t10:00\tx\n2025-01-01\taoi\t09:00\t10:00\tz\n2025-01-02\taoi\t09:00\t10:00\ty\n' > "$t"
out=$(ARCHIVE=$t bash tools/purge-archive --before 2025-01-01) || { echo "purge --before failed"; fail=1; }
[ "$out" = "purged 1 row(s) before 2025-01-01 from $t" ] || { echo "purge output: $out"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 2 ] && grep -q 'z$' "$t" && grep -q 'y$' "$t" || { echo "purge --before kept the wrong rows (the row on the cutoff date must stay)"; fail=1; }
ARCHIVE=$t bash tools/purge-archive --before 2025/06/01 >/dev/null 2>&1; [ $? = 2 ] || { echo "a malformed date should exit 2"; fail=1; }
err=$(ARCHIVE=$t bash tools/purge-archive --before 2025-13-01 2>&1 >/dev/null); [ $? = 2 ] && [ "$err" = "bad date: 2025-13-01 (expected YYYY-MM-DD)" ] || { echo "an out-of-range month should exit 2 with the bad date message: $err"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 2 ] || { echo "a malformed date deleted rows"; fail=1; }
err=$(bash tools/purge-archive 2>&1 >/dev/null); [ "$err" = "usage: purge-archive --all | --before YYYY-MM-DD" ] || { echo "usage line: $err"; fail=1; }
rm -f "$t"; exit $fail

