t=$(mktemp); printf '# h\n2024-12-31\taoi\t09:00\t10:00\tx\n2025-01-02\taoi\t09:00\t10:00\ty\n' > "$t"
out=$(ARCHIVE=$t bash tools/purge-archive --before 2025-01-01) || { echo "purge --before failed"; fail=1; }
[ "$out" = "purged 1 row(s) before 2025-01-01 from $t" ] || { echo "purge output: $out"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 1 ] && grep -q 'y$' "$t" || { echo "purge --before kept the wrong rows"; fail=1; }
ARCHIVE=$t bash tools/purge-archive --before 2025/06/01 >/dev/null 2>&1; [ $? = 2 ] || { echo "a malformed date should exit 2"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 1 ] || { echo "a malformed date deleted rows"; fail=1; }
ARCHIVE=$t bash tools/purge-archive --before 2025-13-01 >/dev/null 2>&1; [ $? = 2 ] || { echo "a month of 13 should exit 2"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 1 ] || { echo "an out-of-range date deleted rows"; fail=1; }
rm -f "$t"

# a row dated on the cutoff is kept; only rows before it are deleted
t=$(mktemp); printf '# h\n2024-12-31\taoi\t09:00\t10:00\tx\n2025-01-01\taoi\t09:00\t10:00\tz\n2025-01-02\taoi\t09:00\t10:00\ty\n' > "$t"
out=$(ARCHIVE=$t bash tools/purge-archive --before 2025-01-01) || { echo "purge --before (same-day row) failed"; fail=1; }
[ "$out" = "purged 1 row(s) before 2025-01-01 from $t" ] || { echo "purge output (same-day row): $out"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 2 ] && grep -q 'z$' "$t" && grep -q 'y$' "$t" || { echo "purge --before deleted the cutoff-day row"; fail=1; }
rm -f "$t"

# with no arguments the usage lists every option
err=$(bash tools/purge-archive 2>&1 >/dev/null); [ $? = 2 ] || { echo "no arguments should exit 2"; fail=1; }
case "$err" in *"--before YYYY-MM-DD"*) ;; *) echo "usage lacks --before: $err"; fail=1 ;; esac
exit $fail
